from content_helpers import code, output, choice, lesson, section, program

def with_functions(task, functions):
    # Explicit function definitions precede main; task remains ordinary app data.
    source = task["solution"]
    index = source.index("int main()")
    task["solution"] = source[:index] + functions + "\n\n" + source[index:]
    if task["kind"] == "output":
        task["starter"] = task["solution"]
    return task

def example(functions, body):
    source = program(body)
    return source.replace("int main()", functions + "\n\nint main()", 1)

