                with_functions(code("cost", "Смета маршрута", 'Напишите int cost(int distance,int rate,int fee), возвращающую distance*rate+fee. main читает distance,rate,fee (0…100) и выводит результат.', 'int distance = 0, rate = 0, fee = 0;\nstd::cin >> distance >> rate >> fee;\nstd::cout << cost(distance, rate, fee);', [("12 3 5", "41"), ("0 8 2", "2"), ("100 100 100", "10100"), ("1 0 0", "0"), ("0 0 100", "100")], ["Фиксированный сбор прибавляется один раз.", "Все данные приходят через три параметра; cin нужен только в main."], "Функция пригодна для любого вызывающего кода, потому что не зависит от способа ввода."), 'int cost(int distance, int rate, int fee) {\n    return distance * rate + fee;\n}'),
                with_functions(output("composition", "Композиция вызовов", 'std::cout << twice(add(2, 3));', "10", ["Сначала нужен результат внутреннего вызова.", "add(2,3) даёт 5, которое передаётся в twice."], "Внешний вызов получает значение внутреннего, а не текст выражения."), 'int add(int a, int b) { return a + b; }\nint twice(int n) { return n * 2; }'),
                with_functions(code("count", "Доступные рейсы", 'Ввод: budget (0…10000), n (0…100), затем n пар distance,rate (0…100). Напишите int cost(int distance,int rate), возвращающую distance*rate. Выведите число рейсов, стоимость которых ≤ budget. Каждый рейс оценивается независимо, бюджет не тратится.', 'int budget = 0, n = 0;\nstd::cin >> budget >> n;\nint count = 0;\nfor (int i = 0; i < n; ++i) {\n    int distance = 0, rate = 0;\n    std::cin >> distance >> rate;\n    if (cost(distance, rate) <= budget) { ++count; }\n}\nstd::cout << count;', [("20 3 5 3 8 4 10 2", "2"), ("0 0", "0"), ("0 2 0 5 1 1", "1"), ("100 3 10 10 1 1 0 0", "3"), ("5 2 1 5 1 6", "1"), ("0 3 0 0 1 0 0 1", "3")], ["Не вычитайте стоимость из бюджета: рейсы независимы.", "При каждой паре сравнивайте результат cost с исходным budget."], "Важное требование — независимость оценок. Оно меняет алгоритм по сравнению с покупкой всех рейсов сразу.", difficulty=2), 'int cost(int distance, int rate) { return distance * rate; }'),
                choice("separation", "Кто должен читать ввод?", 'Функция cost(distance, rate) нужна и экрану, и тестам. Почему лучше не читать std::cin внутри неё?', ["Так её результат зависит только от явно переданных данных и легче проверяется", "В функциях запрещён std::cin", "Без std::cin вычисления всегда быстрее"], 0, ["Речь о разграничении обязанностей, не о запрете языка.", "Тест может вызвать функцию с заданными аргументами без подготовки потока."], "Разделение вычисления и внешнего взаимодействия полезно и для независимого учебного ядра приложения."),
